// Generated by Viscosity: "bs" stored as a struct of arrays (fields x, y, vx, vy, m).
class __Vsc_bs {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.x = new Float64Array(cap); this.y = new Float64Array(cap); this.vx = new Float64Array(cap); this.vy = new Float64Array(cap); this.m = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_bs(Math.max(16, v.length / 5)); for (let i = 0; i < v.length; i += 5) c.push(v[i + 0], v[i + 1], v[i + 2], v[i + 3], v[i + 4]); return c; }
  push(v0, v1, v2, v3, v4) { const n = this.length; if (n === this.cap) this.grow(); this.x[n] = v0; this.y[n] = v1; this.vx[n] = v2; this.vy[n] = v3; this.m[n] = v4; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.x); this.x = t; t = new Float64Array(cap); t.set(this.y); this.y = t; t = new Float64Array(cap); t.set(this.vx); this.vx = t; t = new Float64Array(cap); t.set(this.vy); this.vy = t; t = new Float64Array(cap); t.set(this.m); this.m = t; }
}
// N-body: O(n^2) gravity on 1500 bodies (reads every field of others).
const N = 1500;
const bs = new __Vsc_bs();
for (let i = 0; i < N; i++) {
  bs.push(Math.cos(i) * i, Math.sin(i) * i, 0, 0, 1 + (i % 3));
}
function step(b, dt) {
  for (let i = 0; i < b.length; i++) {
    let ax = 0;
    let ay = 0;
    for (let j = 0; j < b.length; j++) {
      const dx = b.x[j] - b.x[i];
      const dy = b.y[j] - b.y[i];
      const d2 = dx * dx + dy * dy + 0.01;
      const f = b.m[j] / (d2 * Math.sqrt(d2));
      ax += dx * f;
      ay += dy * f;
    }
    b.vx[i] += ax * dt;
    b.vy[i] += ay * dt;
  }
  for (let i = 0; i < b.length; i++) {
    b.x[i] += b.vx[i] * dt;
    b.y[i] += b.vy[i] * dt;
  }
}
const t0 = performance.now();
for (let s = 0; s < 6; s++) step(bs, 0.001);
const ms = performance.now() - t0;
let e = 0;
for (let b = 0; b < bs.length; b++) e += bs.vx[b] * bs.vx[b] + bs.vy[b] * bs.vy[b];
console.log(JSON.stringify({ check: e.toPrecision(12), ms }));
